/bin/zsh -c "docker exec -i invoice-audit-check psql -v ON_ERROR_STOP=1 -U postgres <<'SQL'
INSERT INTO accounts VALUES ('demo-check', true);
INSERT INTO orders(id, account_id) VALUES ('order-check', 'demo-check');
SELECT complete_order('order-check');
SELECT complete_order('order-check');
DO "'$$ BEGIN
  IF (SELECT count(*) FROM invoice_audit WHERE order_id = '"'order-check') <> 1 THEN
    RAISE EXCEPTION 'completion did not append exactly one audit row';
  END IF;
END "'$$;
SET ROLE app;
SET app.allow_audit_delete = '"'true';
DO "'$$ BEGIN
  DELETE FROM invoice_audit WHERE order_id = '"'order-check';
  RAISE EXCEPTION 'app delete was not refused';
EXCEPTION WHEN insufficient_privilege THEN NULL;
END "'$$;
RESET ROLE;
SELECT purge_demo_account('"'demo-check');
DO "'$$ BEGIN
  IF EXISTS (SELECT 1 FROM accounts WHERE id = '"'demo-check') OR EXISTS (SELECT 1 FROM invoice_audit WHERE order_id = 'order-check') THEN
    RAISE EXCEPTION 'demo purge did not remove account and audit';
  END IF;
END "'$$;
SQL
docker stop invoice-audit-check'

